      "action": "ctx['reverselnc'] = max(ctx['reverselnc'], abs(ctx['nums'][-1] - ctx['nums'][ctx['i'] - 1]) - abs(ctx['nums'][ctx['i']] - ctx['nums'][ctx['i'] - 1])); ctx['i'] += 1",
